<script>
$(function(){
    var timer,request,base='{{ url('ca_report') }}';
    function resizeRegister(){var box=document.querySelector('.receipt-scroll');if(!box)return;var heading=document.querySelector('#receiptTable thead tr:first-child');var headingHeight=heading?heading.getBoundingClientRect().height:35;document.querySelectorAll('#receiptTable .filter-row th').forEach(function(cell){cell.style.top=headingHeight+'px'});var available=Math.floor(window.innerHeight-box.getBoundingClientRect().top-18);var height=Math.max(280,available);box.style.height=height+'px';box.style.maxHeight=height+'px'}
    function query(){var p=new URLSearchParams();$.each($('#invoiceFilterForm').serializeArray(),function(_,x){if($.trim(x.value)!=='')p.set(x.name,x.value)});return p.toString()}
    function load(url,update){url=url||base+(query()?'?'+query():'');if(update!==false)history.replaceState({invoiceRegister:true},'',url);if(request)request.abort();$('#receiptTable').addClass('loading');request=$.ajax({url:url,type:'GET',dataType:'json',headers:{'X-Requested-With':'XMLHttpRequest'}}).done(function(r){$('#receiptTable tbody,#receiptTable tfoot').remove();$('#receiptTable').append(r.html);resizeRegister()}).fail(function(x,s){if(s!=='abort')alert('Receipt data could not be loaded. Please try again.');}).always(function(){$('#receiptTable').removeClass('loading')})}
    $('.live-select').on('change',function(){load(null,true)});$('.live-text').on('input',function(){clearTimeout(timer);timer=setTimeout(function(){load(null,true)},450)});$('#invoiceReset').on('click',function(){$('#invoiceFilterForm').find('input,select').val('');load(null,true)});$('#invoiceFilterForm').on('submit',function(e){e.preventDefault();load(null,true)});$(document).on('click','.invoice-register .pagination a',function(e){e.preventDefault();load($(this).attr('href'),true)});window.addEventListener('resize',resizeRegister);window.addEventListener('popstate',function(){location.reload()});resizeRegister();
});
</script>
